import{_ as e,H as l,f as a,i as d}from"./chunks/framework.DLd0CbzH.js";const o=JSON.parse('{"title":"Risk Register — Agelto","description":"","frontmatter":{"type":"risk-register","tags":["agelto","risks","raid"],"created":"2026-06-11T00:00:00.000Z","updated":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/Risk_Register (Agelto).md","filePath":"03_Dev/Risk_Register (Agelto).md"}'),i={name:"03_Dev/Risk_Register (Agelto).md"};function s(n,t,g,r,f,x){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="risk-register-—-agelto" tabindex="-1">Risk Register — Agelto <a class="header-anchor" href="#risk-register-—-agelto" aria-label="Permalink to &quot;Risk Register — Agelto&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Назначение</p><p>Реестр рисков проекта. Базовые 4 риска — из дипломной работы, гл. 3.3 (архив: <code>assets/_Диплом v1.1.docx</code>); инженерные и юридические — из аудита ТЗ 2026-06-11. Финансовая чувствительность (NPV, стресс-границы) — [[03_Financial_Model]] §6.</p></div><div class="info custom-block github-alert"><p class="custom-block-title">Связанные документы</p><p>← [[BRD (Agelto)]] | → [[Открытые вопросы (Agelto)]]</p></div><hr><h2 id="матрица-рисков" tabindex="-1">Матрица рисков <a class="header-anchor" href="#матрица-рисков" aria-label="Permalink to &quot;Матрица рисков&quot;">​</a></h2><p>P — вероятность, I — влияние (Низкий / Средний / Высокий).</p><h3 id="из-диплома-гл-3-3" tabindex="-1">Из диплома (гл. 3.3) <a class="header-anchor" href="#из-диплома-гл-3-3" aria-label="Permalink to &quot;Из диплома (гл. 3.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Риск</th><th style="text-align:left;">Категория</th><th style="text-align:left;">P</th><th style="text-align:left;">I</th><th style="text-align:left;">Митигация</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;">R-1</td><td style="text-align:left;">Низкая точность матчинга, «галлюцинации» ИИ — клиент получает невалидные лиды и несёт убытки</td><td style="text-align:left;">Технологический</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Human-in-the-loop: confidence &lt; 92% → флаг «Требует проверки» → премодерация аналитиком (BRD F-MATCH-6); golden dataset для контроля accuracy</td><td style="text-align:left;">Митигация спроектирована, не реализована</td></tr><tr><td style="text-align:left;">R-2</td><td style="text-align:left;">Блокировка доступа к ЕИС / изменение структуры HTML или формата PDF</td><td style="text-align:left;">Инфраструктурный</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Адаптивные LLM-парсеры (читают макет, а не вёрстку) + PromptRules без деплоя — <strong>уже реализовано в коде</strong>; зеркальные БД; прокси-пул с ротацией</td><td style="text-align:left;">Частично закрыт</td></tr><tr><td style="text-align:left;">R-3</td><td style="text-align:left;">Высокий churn из-за сложности внедрения у клиента</td><td style="text-align:left;">Рыночный</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Setup Service «под ключ» (F-MON-4) + Customer Success для обучения персонала</td><td style="text-align:left;">Процесс не описан → gap</td></tr><tr><td style="text-align:left;">R-4</td><td style="text-align:left;">Ужесточение законодательства по ПД и ИИ</td><td style="text-align:left;">Регуляторный</td><td style="text-align:left;">Низкий</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Только публичные данные тендеров; размещение мощностей в отечественном контуре</td><td style="text-align:left;">⚠️ Подрывается R-5</td></tr></tbody></table><h3 id="добавлено-аудитом" tabindex="-1">Добавлено аудитом <a class="header-anchor" href="#добавлено-аудитом" aria-label="Permalink to &quot;Добавлено аудитом&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Риск</th><th style="text-align:left;">Категория</th><th style="text-align:left;">P</th><th style="text-align:left;">I</th><th style="text-align:left;">Митигация</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;">R-5</td><td style="text-align:left;">🔴 Передача документов тендеров в Google Gemini API противоречит NFR «серверы в РФ» и заявленному «российскому контуру»; блокер для Enterprise/госклиентов</td><td style="text-align:left;">Регуляторный</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Резолюция L3: юр. заключение «публичные данные» / self-hosted LLM / российский API (GigaChat, YandexGPT) как fallback</td><td style="text-align:left;">Митигация спроектирована → [[LLM_Strategy]] Sprint 1–2 (GigaChat РФ + local)</td></tr><tr><td style="text-align:left;">R-6</td><td style="text-align:left;">SPOF Gemini: блокировка Google API из РФ или для РФ останавливает весь AI-пайплайн</td><td style="text-align:left;">Инфраструктурный</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Абстракция AI-провайдера в коде (сейчас GeminiService прибит к Gemini); протестированный fallback-провайдер</td><td style="text-align:left;">Митигация спроектирована → [[LLM_Strategy]] Sprint 1 (ProviderRouter)</td></tr><tr><td style="text-align:left;">R-7</td><td style="text-align:left;">Рост стоимости токенов / превышение бюджета AI: себестоимость обработки сметы не посчитана, маржа тарифов неизвестна</td><td style="text-align:left;">Финансовый</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Cost-метрики per-документ (T5); расчёт unit-экономики токенов до фиксации тарифов; context cache уже снижает затраты</td><td style="text-align:left;">Митигация спроектирована → [[LLM_Strategy]] Sprint 2 (cost-метрики per-doc)</td></tr><tr><td style="text-align:left;">R-8</td><td style="text-align:left;">Тихая деградация качества парсинга при изменении PromptRules (нет регрессионных тестов промптов)</td><td style="text-align:left;">Технологический</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Регламент QA: golden dataset из N эталонных смет, прогон перед активацией новой версии промпта; откат через версионирование (уже в коде)</td><td style="text-align:left;">Откат есть; регламент → [[LLM_Strategy]] Sprint 3 (smeta:validate-prompt)</td></tr><tr><td style="text-align:left;">R-9</td><td style="text-align:left;">Демпинг / копирование функционала игроками Gen1 (Seldon, Тендерплан)</td><td style="text-align:left;">Конкурентный</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Фокус на узких коллекциях (ЖБИ, кабель, металл); технологический гандикап 18–24 мес.; накопленные обучающие данные как барьер</td><td style="text-align:left;">Принят (мониторинг)</td></tr><tr><td style="text-align:left;">R-10</td><td style="text-align:left;">Потеря данных: нет backup-политики PostgreSQL и хранилища оригиналов документов, RPO/RTO не определены</td><td style="text-align:left;">Инфраструктурный</td><td style="text-align:left;">Низкий</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Определить RPO/RTO (T7); автоматический backup PG; S3-совместимое хранилище для оригиналов (диплом гл. 3.1)</td><td style="text-align:left;">Открыт</td></tr><tr><td style="text-align:left;">R-11</td><td style="text-align:left;">Результат закупки не отслеживается: победитель / уклонение / расторжение не фиксируются → лид может быть преждевременным (адресат закупки материалов — победитель, а не заказчик) или протухшим</td><td style="text-align:left;">Продуктовый</td><td style="text-align:left;">Средний</td><td style="text-align:left;">Высокий</td><td style="text-align:left;">Мониторинг статуса закупки + парсинг протокола итогов — проектируется в [[ADR-002_Winner_Tracking_And_Monitoring]] + [[Procurement_Lifecycle]]</td><td style="text-align:left;">Предложено, требует бизнес-валидации</td></tr></tbody></table><hr><h2 id="правила-ведения" tabindex="-1">Правила ведения <a class="header-anchor" href="#правила-ведения" aria-label="Permalink to &quot;Правила ведения&quot;">​</a></h2><ul><li>Новый риск → строка с очередным R-N, категория, P/I, митигация, статус</li><li>Риск закрыт → статус «закрыт (дата, как)», строку не удалять</li><li>Пересмотр — при каждом аудите ТЗ или после инцидента</li></ul>',13)])])}const h=e(i,[["render",s]]);export{o as __pageData,h as default};
